def solve_math_problem(max_coordinate: int, area_lower: int, area_upper: int) -> int:
    """Count axis-parallel rectangles in an integer grid with area in (area_lower, area_upper]."""
    if max_coordinate < 0:
        raise ValueError("max_coordinate must be non-negative")
    if area_lower >= area_upper:
        return 0

    count = 0
    for width in range(1, max_coordinate + 1):
        horizontal_placements = max_coordinate + 1 - width
        for height in range(1, max_coordinate + 1):
            area = width * height
            if area_lower < area <= area_upper:
                vertical_placements = max_coordinate + 1 - height
                count += horizontal_placements * vertical_placements

    return count

